#!/usr/bin/env bash
# Publish the approved paths from a maintenance task through the shared PR flow.
set -euo pipefail
base="${BASE:-main}"
# FILES is supplied by the reusable task workflow.
# shellcheck disable=SC2153
read -r -a files <<< "$FILES"
if [ "${#files[@]}" -eq 0 ]; then echo 'No approved output paths' >&2; exit 1; fi
if [ -z "$(git status --porcelain -- "${files[@]}")" ]; then exit 0; fi
existing="$(gh pr list --base "$base" --head "$BRANCH" --state open --json number --jq '.[0].number // empty')"
lease=""
remote_status=0
remote="$(git ls-remote --exit-code --heads origin "refs/heads/$BRANCH")" || remote_status=$?
case "$remote_status" in
  0)
    lease="${remote%%[[:space:]]*}"
    git fetch --quiet origin "refs/heads/$BRANCH"
    if [ -n "${FAILED_SHA:-}" ] && [ "$lease" != "$FAILED_SHA" ]; then
      echo 'Repair target changed during task execution' >&2
      exit 1
    fi
    if [ -n "$existing" ] && [ -n "${DIFF_VALIDATOR:-}" ]; then
      python3 "$DIFF_VALIDATOR" "origin/$base" "$lease"
    fi
    ;;
  2) ;;
  *) exit "$remote_status" ;;
esac
# Tasks may stage their own edits; rebuild the index from approved paths.
git reset --quiet HEAD
paths=()
for path in "${files[@]}"; do
  if [ -e "$path" ] || [ -L "$path" ] || [ -n "$(git ls-files -- "$path")" ]; then paths+=("$path"); fi
done
git switch -C "$BRANCH"
git add -- "${paths[@]}"
git commit -m "$PR_TITLE"
if [ -n "${DIFF_VALIDATOR:-}" ]; then python3 "$DIFF_VALIDATOR" "origin/$base" HEAD; fi
if [ -n "$existing" ] && git diff --quiet "$lease" HEAD -- "${files[@]}"; then
  echo "PR #$existing already has this output."
  exit 0
fi
git push --force-with-lease="refs/heads/$BRANCH:$lease" origin "HEAD:refs/heads/$BRANCH"
body="$(mktemp)"
trap 'rm -f "$body"' EXIT
cat > "$body" <<BODY
## Description

${PR_TITLE}
Generated by the [${TASK_NAME} workflow run](${RUN_URL}).
BODY
if [ -s "${RATIONALE_FILE:-/tmp/agent_rationale.md}" ]; then cat "${RATIONALE_FILE:-/tmp/agent_rationale.md}" >> "$body"; fi
cat >> "$body" <<'BODY'

## How Has This Been Tested?

The task validation and required pull request checks validate this update.

## Docs

- [ ] Customer-facing change: I updated documentation.
- [x] No docs change needed (automated maintenance).

## Additional Options

- [ ] [Optional] Please cherry-pick this PR to the latest release version.
BODY
if [ -z "$existing" ]; then
  gh pr create --base "$base" --head "$BRANCH" --title "$PR_TITLE" --body-file "$body"
  existing="$(gh pr list --base "$base" --head "$BRANCH" --state open --json number --jq '.[0].number // empty')"
fi
edit_args=(--body-file "$body")
if [ -n "${REVIEWER:-}" ]; then edit_args+=(--add-reviewer "$REVIEWER"); fi
gh pr edit "$existing" "${edit_args[@]}"
printf 'pr_number=%s\npr_url=%s/pull/%s\n' "$existing" "$REPO_URL" "$existing" >> "$GITHUB_OUTPUT"
